1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="UTF-8">
5	<title>Tiling and Swizzling with 3D TMA</title>
6	<link rel="stylesheet" href="../viz-base.css">
7	<script src="../viz-base.js"></script>
8	<style>
9	  .main { display:flex; gap:16px; max-width:1300px; margin:0 auto; align-items:center; justify-content:center;
10	    position:relative; }
11	  .mat-box { background:var(--surface); border-radius:10px; padding:14px; border:1px solid var(--border);
12	    box-shadow:0 1px 3px rgba(0,0,0,.06); text-align:center; }
13	  .mat-box h2 { font-size:14px; font-weight:700; margin-bottom:2px; }
14	  .mat-box .dims { font-size:11px; color:var(--dim); margin-bottom:6px; font-weight:600; }
15	
16	  .grid { display:inline-grid; gap:0; }
17	  .hdr { font-size:8px; color:var(--dim); text-align:center; padding:1px 0; font-weight:600; }
18	  .rl { font-size:8px; color:var(--dim); display:flex; align-items:center; justify-content:flex-end;
19	    padding-right:2px; font-weight:600; }
20	
21	  /* Global memory cells */
22	  .gc {
23	    border-radius:2px; display:flex; align-items:center; justify-content:center;
24	    font-size:5px; font-weight:700; border:1px solid transparent; transition:all .1s;
25	    min-width:0; color:var(--text);
26	  }
27	  .gc.idle { background:#dde0e4; opacity:1; }
28	  .gc.inbox { background:var(--color-hover-bg); border-color:var(--accent); color:var(--color-hover-text);
29	    cursor:pointer; opacity:1; }
30	  .gc.hov { border-color:#222; border-width:2px; z-index:2; box-shadow:0 0 5px rgba(59,130,246,.4); }
31	
32	  /* Shared memory cells (tiling-exploration style) */
33	  .sc {
34	    display:flex; align-items:center; justify-content:center;
35	    font-size:7px; font-weight:700; border:1px solid rgba(255,255,255,.15); transition:all .15s;
36	    min-width:0; color:#fff; text-shadow:0 1px 1px rgba(0,0,0,.2);
37	  }
38	  .sc.rd { outline:2.5px solid #222; outline-offset:-1px; z-index:1; }
39	  .sc.dm { opacity:.18; }
40	
41	  /* Group labels */
42	  .groups { display:flex; gap:8px; justify-content:center; }
43	  .group-label { text-align:center; font-size:11px; font-weight:700; color:var(--accent); margin-bottom:4px; }
44	  .atom-start { border-top:3px solid #273142 !important; }
45	
46	  .arrow-box { display:flex; flex-direction:column; align-items:center; gap:4px; padding:0 10px; }
47	  .arrow-box .arrow { font-size:32px; color:var(--accent); }
48	  .arrow-box .label { font-size:13px; font-weight:700; color:var(--accent); }
49	  .arrow-box .detail { font-size:10px; color:var(--dim); font-weight:600; text-align:center; line-height:1.5; }
50	
51	  .arrow-svg { position:absolute; top:0; left:0; width:100%; height:100%; pointer-events:none; z-index:10; overflow:visible; }
52	  .arrow-svg path { fill:none; stroke:#222; stroke-width:1.5; }
53	  .arrow-svg text { font-size:11px; font-weight:600; fill:#222; font-family:inherit; }
54	
55	  .info { max-width:1300px; margin:14px auto 0; background:var(--surface); border:1px solid var(--border);
56	    border-radius:8px; padding:10px 16px; font-size:13px; line-height:1.6; }
57	  .info b { font-weight:700; }
58	  .info .formula { font-family:'SF Mono','Fira Code',monospace; color:var(--accent); font-weight:600; }
59	
60	  .leg { gap:0; margin-top:12px; }
61	</style>
62	</head>
63	<body>
64	
65	<h1>Moving Multiple Swizzle Atoms with 3D TMA</h1>
66	<div class="sub">Split each 256-byte row into two 128-byte groups, then swizzle each group independently</div>
67	
68	<div class="controls">
69	  <div><span class="lbl">Swizzle</span>
70	    <div class="bg" id="sw">
71	      <button class="btn" data-v="none">None</button>
72	      <button class="btn on" data-v="128">128B</button>
73	    </div>
74	  </div>
75	  <div><span class="lbl">Col offset</span><div class="bg" id="cc"></div></div>
76	</div>
77	
78	<div class="main" id="main">
79	  <svg class="arrow-svg" id="arrowsvg"></svg>
80	
81	  <div class="mat-box">
82	    <h2 style="color:var(--color-group-2)">Global Memory</h2>
83	    <div class="dims">16&times;256 fp16 (each cell = 8 fp16 = 16B)</div>
84	    <div class="grid" id="gg"></div>
85	  </div>
86	
87	  <div class="arrow-box">
88	    <div class="arrow">&rarr;</div>
89	    <div class="label">3D TMA</div>
90	    <div class="detail" id="tmainfo"></div>
91	  </div>
92	
93	  <div class="mat-box">
94	    <h2 style="color:var(--color-group-4)">Shared Memory (grouped into atoms and swizzled)</h2>
95	    <div class="groups" id="gs"></div>
96	  </div>
97	</div>
98	
99	<div class="info" id="infobox"></div>
100	
101	<div class="leg">
102	  <div class="leg-row" id="sl"></div>
103	</div>
104	
105	<script>
106	var BK = ['#5b9bd5','#ed9a3c','#d95555','#45b5a5','#5fb85f','#e0b828','#9d6eb5','#e87888'];
107	
108	var GDR = 16;          // global rows
109	var GDC = 32;          // global sector columns (256 fp16 / 8 per sector)
110	var NGROUPS = 2;       // groups per TMA load
111	var TOTAL_GROUPS = 4;  // total groups across full row (256 fp16 / 64)
112	var GSECS = 8;         // sectors per group (64 fp16 = 128B = one swizzle atom width)
113	var BOX_R = 8;         // TMA box rows
114	var ROW_BYTES = 512;   // 256 fp16 × 2B
115	var GRP_BYTES = 128;   // 64 fp16 × 2B per group
116	var GCSZ = 10;         // global cell size
117	var SCSZ = 12;         // shared cell size
118	
119	var ST = { sw: '128', col: 0, hovR: -1, hovC: -1, hovGi: 0 };
120	
121	function mk(t, c) { var d = document.createElement(t); if (c) d.className = c; return d; }
122	
123	function draw() {
124	  var useSw = ST.sw === '128';
125	  var colOff = ST.col;                          // which pair of groups (0 or 1)
126	  var boxGrp = NGROUPS;                         // always all groups
127	  var boxRows = GDR;                            // always all 16 rows
128	
129	  // Box in global: contiguous rectangle
130	  var colBase = colOff * NGROUPS * GSECS;       // sector offset for col
131	  var boxColStart = colBase;
132	  var boxColEnd = colBase + NGROUPS * GSECS;
133	
134	  // TMA info
135	  var globalGStart = colOff * NGROUPS;
136	  document.getElementById('tmainfo').innerHTML =
137	    'cp.async.bulk.tensor.3d<br>(row=0, group=' + globalGStart + ', col=0)' +
138	    (useSw ? '<br>+ SWIZZLE_128B' : '');
139	
140	
141	  // Info box
142	  var swName = useSw ? 'CU_TENSOR_MAP_SWIZZLE_128B' : 'CU_TENSOR_MAP_SWIZZLE_NONE';
143	  document.getElementById('infobox').innerHTML =
144	    '<b>TensorMap</b>: <span class="formula">' +
145	    'dtype = f16, globalDim = [64, 16, ' + TOTAL_GROUPS + '], globalStrides = [512B, 128B], ' +
146	    'boxDim = [64, 16, 2], swizzle = ' + swName + '</span><br>' +
147	    '<b>Instruction</b>: <span class="formula">cp.async.bulk.tensor.3d.shared::cta.global.mbarrier::complete_tx::bytes [smem], [tensormap, {' +
148	    '0, 0, ' + globalGStart + '}], [mbar]</span><br>' +
149	    '<b>Coordinate split</b>: <span class="formula">16\u00d7128 fp16 slice \u2192 ' +
150	        'reshape(16, 2, 64).transpose(1, 0, 2)' +
151	        ' \u2192 (group=2, row=16, col=64)</span><br>' +
152	    '<b>Note</b>: TensorMap and PTX list dimensions from innermost to outermost, so the instruction order is the reverse of the (group, row, col) order shown in the diagram.';
153	
154	  // Global memory: single contiguous grid
155	  var gg = document.getElementById('gg');
156	  gg.innerHTML = '';
157	  gg.style.gridTemplateColumns = 'repeat(' + GDC + ',' + GCSZ + 'px)';
158	  for (var r = 0; r < GDR; r++) {
159	    for (var c = 0; c < GDC; c++) {
160	      var d = mk('div', 'gc');
161	      d.style.width = GCSZ + 'px';
162	      d.style.height = GCSZ + 'px';
163	      var inBox = (c >= boxColStart && c < boxColEnd);
164	      if (inBox) {
165	        d.classList.add('inbox');
166	        var cellGi = Math.floor((c - colBase) / GSECS);
167	        var lr = r;
168	        var lc = c - colBase - cellGi * GSECS;
169	        d.dataset.lr = lr;
170	        d.dataset.lc = lc;
171	        d.dataset.gi = cellGi;
172	        if (ST.hovR === lr && ST.hovC === lc && ST.hovGi === cellGi) d.classList.add('hov');
173	      } else {
174	        d.classList.add('idle');
175	      }
176	      gg.appendChild(d);
177	    }
178	  }
179	
180	  // Shared memory: two groups side by side
181	  var gs = document.getElementById('gs');
182	  gs.innerHTML = '';
183	
184	  for (var gi = 0; gi < NGROUPS; gi++) {
185	    var gd = mk('div', 'group');
186	    var glabel = mk('div', 'group-label');
187	    glabel.textContent = 'g' + gi + ' (2 atoms)';
188	    gd.appendChild(glabel);
189	
190	    var grid = mk('div', 'grid');
191	    var showRL = (gi === 0);
192	    grid.style.gridTemplateColumns = '16px repeat(' + GSECS + ',' + SCSZ + 'px)';
193	
194	    // Column headers
195	    grid.appendChild(mk('div', 'hdr'));
196	    for (var s = 0; s < GSECS; s++) {
197	      var h = mk('div', 'hdr');
198	      h.textContent = 's' + s;
199	      grid.appendChild(h);
200	    }
201	
202	    // Rows (16 rows × 8 sectors per group)
203	    for (var r = 0; r < GDR; r++) {
204	      var rl = mk('div', 'rl');
205	      if (showRL) rl.textContent = r;
206	      if (r === 8) rl.classList.add('atom-start');
207	      grid.appendChild(rl);
208	      for (var p = 0; p < GSECS; p++) {
209	        var logCol = useSw ? (p ^ (r % 8)) : p;
210	
211	        var d = mk('div', 'sc');
212	        d.style.width = SCSZ + 'px';
213	        d.style.height = SCSZ + 'px';
214	        d.style.background = BK[p % 8];
215	        d.textContent = logCol;
216	        if (r === 8) d.classList.add('atom-start');
217	
218	        // Is this cell in the TMA box?
219	        var inBox = true;  // always all groups, all rows
220	        if (inBox) {
221	          d.classList.add('rd');
222	          // Mark hover target
223	          if (ST.hovR >= 0 && gi === ST.hovGi) {
224	            var destSec = useSw ? (ST.hovC ^ (ST.hovR % 8)) : ST.hovC;
225	            if (r === ST.hovR && p === destSec) {
226	              d.id = 'shov';
227	            }
228	          }
229	        } else {
230	          d.classList.add('dm');
231	        }
232	
233	        grid.appendChild(d);
234	      }
235	    }
236	
237	    gd.appendChild(grid);
238	    gs.appendChild(gd);
239	  }
240	
241	  drawArrow();
242	
243	  // Legend
244	  var sl = document.getElementById('sl');
245	  sl.innerHTML = '';
246	  for (var i = 0; i < 8; i++) {
247	    var li = mk('div', 'li');
248	    var sw = mk('div', 'swtch');
249	    sw.style.background = BK[i];
250	    li.appendChild(sw);
251	    li.appendChild(document.createTextNode('sector ' + i));
252	    sl.appendChild(li);
253	  }
254	}
255	
256	function drawArrow() {
257	  var svg = document.getElementById('arrowsvg');
258	  svg.innerHTML = '';
259	  if (ST.hovR < 0) return;
260	
261	  var mainEl = document.getElementById('main');
262	  var gCell = document.querySelector('.gc.hov');
263	  var sCell = document.getElementById('shov');
264	  if (!gCell || !sCell) return;
265	
266	  var pr = mainEl.getBoundingClientRect();
267	  var ga = gCell.getBoundingClientRect();
268	  var sa = sCell.getBoundingClientRect();
269	  var x1 = ga.left + ga.width / 2 - pr.left;
270	  var y1 = ga.top + ga.height / 2 - pr.top;
271	  var x2 = sa.left + sa.width / 2 - pr.left;
272	  var y2 = sa.top + sa.height / 2 - pr.top;
273	  var mx = (x1 + x2) / 2;
274	  var my = Math.min(y1, y2) - 40;
275	
276	  var ns = 'http://www.w3.org/2000/svg';
277	  var defs = document.createElementNS(ns, 'defs');
278	  var marker = document.createElementNS(ns, 'marker');
279	  marker.setAttribute('id', 'ah');
280	  marker.setAttribute('markerWidth', '8');
281	  marker.setAttribute('markerHeight', '6');
282	  marker.setAttribute('refX', '7');
283	  marker.setAttribute('refY', '3');
284	  marker.setAttribute('orient', 'auto');
285	  var poly = document.createElementNS(ns, 'polygon');
286	  poly.setAttribute('points', '0 0, 8 3, 0 6');
287	  poly.setAttribute('fill', '#222');
288	  marker.appendChild(poly);
289	  defs.appendChild(marker);
290	  svg.appendChild(defs);
291	
292	  var path = document.createElementNS(ns, 'path');
293	  path.setAttribute('d', 'M' + x1 + ',' + y1 + ' Q' + mx + ',' + my + ' ' + x2 + ',' + y2);
294	  path.setAttribute('marker-end', 'url(#ah)');
295	  svg.appendChild(path);
296	
297	  var useSw = ST.sw === '128';
298	  if (useSw) {
299	    var tx = document.createElementNS(ns, 'text');
300	    tx.setAttribute('x', mx);
301	    tx.setAttribute('y', my - 4);
302	    tx.setAttribute('text-anchor', 'middle');
303	    tx.textContent = 'col ' + ST.hovC + ' XOR (row ' + ST.hovR + ' % 8) = sector ' + ((ST.hovC ^ (ST.hovR % 8)) % 8);
304	    svg.appendChild(tx);
305	  }
306	}
307	
308	(function init() {
309	  document.getElementById('sw').onclick = function(e) {
310	    var b = e.target.closest('.btn'); if (!b) return;
311	    ST.sw = b.dataset.v;
312	    document.querySelectorAll('#sw .btn').forEach(function(x) { x.classList.remove('on'); });
313	    b.classList.add('on');
314	    ST.hovR = -1; ST.hovC = -1;
315	    draw();
316	  };
317	
318	  // Col offset buttons: 0, 128
319	  var cc = document.getElementById('cc');
320	  var colChoices = [{v:0,t:'0'},{v:1,t:'128'}];
321	  for (var i = 0; i < colChoices.length; i++) {
322	    var b = mk('button', 'btn' + (i === 0 ? ' on' : ''));
323	    b.textContent = colChoices[i].t;
324	    b.onclick = (function(v) { return function() {
325	      ST.col = v;
326	      cc.querySelectorAll('.btn').forEach(function(x) { x.classList.remove('on'); });
327	      this.classList.add('on');
328	      ST.hovR = -1; ST.hovC = -1;
329	      draw();
330	    }; })(colChoices[i].v);
331	    cc.appendChild(b);
332	  }
333	
334	  // Hover handlers
335	  var mainEl = document.getElementById('main');
336	  mainEl.addEventListener('mouseenter', function(e) {
337	    var cell = e.target.closest('.gc.inbox');
338	    if (!cell) return;
339	    ST.hovR = +cell.dataset.lr;
340	    ST.hovC = +cell.dataset.lc;
341	    ST.hovGi = +(cell.dataset.gi || 0);
342	    draw();
343	  }, true);
344	  mainEl.addEventListener('mouseleave', function(e) {
345	    var cell = e.target.closest('.gc.inbox');
346	    if (!cell) return;
347	    ST.hovR = -1;
348	    ST.hovC = -1;
349	    draw();
350	  }, true);
351	
352	  draw();
353	})();
354	</script>
355	</body>
356	</html>
