82	<body>
83	
84	<h1>Swizzle Atoms — All Formats</h1>
85	<div class="sub">A swizzle atom is the basic contiguous region in memory where swizzle is applied</div>
86	
87	<div class="anno">
88	  <div class="tag">
89	    <span class="lbl" style="margin-right:2px">Format</span>
90	    <span class="bg" id="fmt">
91	      <button class="btn on" data-v="128">128B</button>
92	      <button class="btn" data-v="64">64B</button>
93	      <button class="btn" data-v="32">32B</button>
94	      <button class="btn" data-v="16">16B interleaved (no XOR swizzle)</button>
95	    </span>
96	  </div>
97	  <span id="annos-tags"></span>
98	
99	</div>
