  };
  document.getElementById('dt').onclick = e => {
    const b = e.target.closest('.btn'); if (!b) return;
    ST.dsize = +b.dataset.v;
    document.querySelectorAll('#dt .btn').forEach(x => x.classList.remove('on')); b.classList.add('on');
    draw();
  };
  rebuildCols();

  // Legend
  const lg = document.getElementById('lg');
  const r1 = mk('div', 'leg-row');
  for (let i = 0; i < SECS; i++) { const d = mk('div', 'li'), w = mk('div', 'swtch'); w.style.background = BK[i]; d.appendChild(w); d.appendChild(document.createTextNode('Sector ' + i)); r1.appendChild(d); }
  lg.appendChild(r1);
  const r2 = mk('div', 'leg-row');
  r2.appendChild(Object.assign(mk('div', 'li'), {innerHTML: '<div class="swtch" style="background:var(--color-hover-bg);border:2.5px solid var(--accent)"></div> Source in original'}));
  r2.appendChild(Object.assign(mk('div', 'li'), {innerHTML: '<div class="swtch brd"></div> Selected read in swizzled view'}));
  r2.appendChild(Object.assign(mk('div', 'li'), {textContent: 'Cell value = original sector column'}));
  r2.appendChild(Object.assign(mk('div', 'li'), {textContent: 'g = explicit 128B group; span = 0 or 1 for the two 128B ranges in a 256B row'}));
  lg.appendChild(r2);

  draw();
})();
</script>
</body>
</html>
